import{Z as t,e,f as n,a0 as a}from"./chunks/framework.DmpHOl9T.js";const c=JSON.parse('{"title":"Integrations","description":"","frontmatter":{},"headers":[],"relativePath":"guides/integrations/index.md","filePath":"guides/integrations/index.md","lastUpdated":1782532814000}'),o={name:"guides/integrations/index.md"};function r(s,i,g,u,d,l){return e(),n("div",null,[...i[0]||(i[0]=[a('<h1 id="integrations" tabindex="-1">Integrations <a class="header-anchor" href="#integrations" aria-label="Permalink to &quot;Integrations&quot;">​</a></h1><p>Connecting forms to CRMs, marketing tools, automations, and custom providers.</p><h2 id="building-a-crm-integration-from-scratch" tabindex="-1"><a href="/guides/integrations/building-a-crm-integration-from-scratch">Building a CRM Integration from Scratch</a> <a class="header-anchor" href="#building-a-crm-integration-from-scratch" aria-label="Permalink to &quot;[Building a CRM Integration from Scratch](/guides/integrations/building-a-crm-integration-from-scratch)&quot;">​</a></h2><p>Formie ships with dozens of CRM integrations, but you can register your own when your provider is not covered. This walkthrough builds a complete multi-object CRM connector from a Craft module — connection settings, field mapping, and sending payloads — step by step.</p><h2 id="building-an-automation-integration-from-scratch" tabindex="-1"><a href="/guides/integrations/building-an-automation-integration-from-scratch">Building an Automation Integration from Scratch</a> <a class="header-anchor" href="#building-an-automation-integration-from-scratch" aria-label="Permalink to &quot;[Building an Automation Integration from Scratch](/guides/integrations/building-an-automation-integration-from-scratch)&quot;">​</a></h2><p>Formie ships automation integrations out of the box, including Web Request, Zapier, and Make. When you need your own endpoint or payload shape, this walkthrough builds a custom automation integration — URL per form, test payload from the builder, and POST on submit.</p><h2 id="building-an-email-marketing-integration-from-scratch" tabindex="-1"><a href="/guides/integrations/building-an-email-marketing-integration-from-scratch">Building an Email Marketing Integration from Scratch</a> <a class="header-anchor" href="#building-an-email-marketing-integration-from-scratch" aria-label="Permalink to &quot;[Building an Email Marketing Integration from Scratch](/guides/integrations/building-an-email-marketing-integration-from-scratch)&quot;">​</a></h2><p>Formie ships with dozens of email marketing integrations, but you can register your own when your provider is not covered. This walkthrough builds a complete list-and-mapping connector from a Craft module — API connection, list picker, field mapping, and subscribe on submit — step by step.</p><h2 id="creating-oauth-integrations-with-formie" tabindex="-1"><a href="/guides/integrations/creating-oauth-integrations-with-formie">Creating OAuth Integrations with Formie</a> <a class="header-anchor" href="#creating-oauth-integrations-with-formie" aria-label="Permalink to &quot;[Creating OAuth Integrations with Formie](/guides/integrations/creating-oauth-integrations-with-formie)&quot;">​</a></h2><p>OAuth is awkward to implement yourself — token storage, refresh flows, provider quirks, and scope handling add up quickly. Formie uses <a href="https://github.com/verbb/auth" target="_blank" rel="noreferrer">Verbb Auth</a> under the hood. This walkthrough registers a custom OAuth integration in a Craft module, connects it in the control panel, and calls the provider API from your code.</p><h2 id="re-run-failed-integrations-from-the-control-panel" tabindex="-1"><a href="/guides/integrations/re-run-failed-integrations-from-the-control-panel">Re-Run Failed Integrations from the Control Panel</a> <a class="header-anchor" href="#re-run-failed-integrations-from-the-control-panel" aria-label="Permalink to &quot;[Re-Run Failed Integrations from the Control Panel](/guides/integrations/re-run-failed-integrations-from-the-control-panel)&quot;">​</a></h2><p>Integrations can fail when a provider is down, credentials expire, or mapping sends invalid data. Formie lets operators manually re-trigger an integration for an existing submission from the control panel — without resubmitting the form or writing custom code.</p><h2 id="integration-dispatch-and-policies" tabindex="-1"><a href="/guides/integrations/integration-dispatch-and-policies">Integration Dispatch and Policies</a> <a class="header-anchor" href="#integration-dispatch-and-policies" aria-label="Permalink to &quot;[Integration Dispatch and Policies](/guides/integrations/integration-dispatch-and-policies)&quot;">​</a></h2><p>Formie separates <strong>what</strong> an integration does (credentials, mapping, API calls) from <strong>when and how</strong> it runs on each submission. The form builder’s Integrations tab controls dispatch behaviour — order, queue vs immediate execution, re-run policies, and per-integration conditions — without changing your integration PHP.</p><h2 id="using-guzzle-clients-from-formie-integrations-in-your-own-code" tabindex="-1"><a href="/guides/integrations/using-guzzle-clients-from-formie-integrations-in-your-own-code">Using Guzzle Clients from Formie Integrations in Your Own Code</a> <a class="header-anchor" href="#using-guzzle-clients-from-formie-integrations-in-your-own-code" aria-label="Permalink to &quot;[Using Guzzle Clients from Formie Integrations in Your Own Code](/guides/integrations/using-guzzle-clients-from-formie-integrations-in-your-own-code)&quot;">​</a></h2><p>Formie supports more than 50 integrations — Mailchimp, HubSpot, Salesforce, Google Sheets, and many others. Each one configures a Guzzle client with the correct authentication, base URI, and error handling. You can reuse that work in your own PHP or Twig code without reimplementing OAuth or API credentials.</p>',16)])])}const m=t(o,[["render",r]]);export{c as __pageData,m as default};
